begin;set local search_path=public,extensions;select plan(20);
select ok((select relrowsecurity from pg_class where oid='public.benchmark_registry_versions'::regclass),'registry RLS enabled');
select ok(not has_table_privilege('authenticated','private.benchmark_verified_sources','SELECT'),'source evidence stays private');
select ok((select indexdef like'%WHERE (status = ''ACTIVE''%'from pg_indexes where indexname='benchmark_registry_one_active_uidx'),'one active metric segment registry');
select ok((select p.prosrc like'%minimum_value%'and p.prosrc like'%maximum_value%'and p.prosrc like'%BENCHMARK_VALUE_OUT_OF_BOUNDS%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='submit_benchmark_contribution'),'exact versioned bounds prevent extremes');
select ok((select p.prosrc like'%benchmark_verified_sources%'and p.prosrc like'%BENCHMARK_SOURCE_VALUE_NOT_VERIFIED%'and p.prosrc like'%source_row.binding_hash=private.canonical_request_hash%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='submit_benchmark_contribution'),'verified value-bound provenance prevents poisoning');
select ok((select p.prosrc like'%pg_advisory_xact_lock%'and p.prosrc like'%max(version)%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='enforce_solution_bundle_version_sequence'),'bundle versions serialize');
select ok((select p.prosrc like'%pg_advisory_xact_lock%'and p.prosrc like'%max(version)%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='enforce_benchmark_policy_version_sequence'),'policy versions serialize');
select ok((select p.prosrc like'%pg_advisory_xact_lock%'and p.prosrc like'%max(version)%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='publish_benchmark_registry_version'),'registry versions serialize before allocation');
select ok((select p.prosrc like'%begin_contract_command%'and p.prosrc like'%BenchmarkRegistryPublishedV1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='publish_benchmark_registry_version'),'registry publication is replay-safe and outboxed');
select ok((select p.prosrc like'%has_org_role%'and p.prosrc like'%BENCHMARK_CONTRIBUTION_DENIED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='submit_benchmark_contribution'),'submission enforces tenant ownership');
select ok((select p.prosrc like'%BENCHMARK_METRIC_SEGMENT_NOT_REGISTERED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='submit_benchmark_contribution'),'unknown metric or segment denied');
select ok((select p.prosrc like'%p_input_version!~registry.input_version_pattern%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='verify_benchmark_source'and pg_get_function_identity_arguments(p.oid)like'%p_value_exact numeric%')and(select p.prosrc like'%source_row.input_version=p_input_version%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='submit_benchmark_contribution'),'input provenance version is registry-validated then bound at submission');
select ok((select p.prosrc like'%BenchmarkContributionAcceptedV3%'and p.prosrc like'%audit_events%'and p.prosrc like'%source_verification_id%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='submit_benchmark_contribution'),'accepted value-bound contribution is audited and outboxed');
select ok((select count(*)=2 from pg_trigger where not tgisinternal and tgname in('solution_bundle_version_sequence','benchmark_policy_version_sequence')),'bundle and policy concurrency triggers installed');
select ok((select count(distinct p.proname)=3 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['publish_benchmark_registry_version','verify_benchmark_source','submit_benchmark_contribution'])and p.prosecdef and p.proconfig::text like'%search_path=%'),'registry commands have fixed security boundaries');
select ok(not has_function_privilege('anon','public.submit_benchmark_contribution(uuid,text,text,date,date,numeric,text,text,text,uuid)','EXECUTE'),'anonymous poisoning denied');
select ok((select p.prosrc like'%IDEMPOTENCY_PAYLOAD_MISMATCH%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='begin_contract_command'),'replay mismatch fails cleanly');
select ok((select p.prosrc like'%INVALID_BUNDLE_VERSION_SEQUENCE%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='enforce_solution_bundle_version_sequence'),'stale concurrent bundle publication denied');
select ok((select p.prosrc like'%INVALID_BENCHMARK_POLICY_VERSION_SEQUENCE%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='enforce_benchmark_policy_version_sequence'),'stale concurrent policy publication denied');
select ok(not exists(select 1 from information_schema.columns where table_schema in('public','private')and table_name in('benchmark_registry_versions','benchmark_verified_sources')and data_type in('real','double precision')),'registry and source values use no float');
select*from finish();rollback;
